  page('layanan.html','Layanan kesehatan & diagnostik','Jalur layanan Queen Health, Queen Lab, Corporate Health, Care dan Wellness dalam AVA Global Ecosystem.',intro('SERVICES / TEMUKAN JALUR ANDA','Layanan yang dimulai<br>dari kebutuhan Anda.','Pilih jalur untuk kebutuhan kesehatan, pemeriksaan laboratorium, program perusahaan, atau Care & Wellness. Ketersediaan lokasi, jadwal, tenaga, dan layanan dikonfirmasi oleh tim AVA sebelum kunjungan.')+`<section class="section wrap"><div class="need-grid"><article>${statusBadge('confirm','PERLU KONFIRMASI')}<span class="need-icon" aria-hidden="true">✚</span><h2>Queen Health</h2><p>Informasi pelayanan kesehatan, koordinasi pemeriksaan, dan tindak lanjut bagi individu serta keluarga.</p><a class="text-link" href="public/brand-health.html">Lihat jalur layanan →</a></article><article>${statusBadge('confirm','PERLU KONFIRMASI')}<span class="need-icon" aria-hidden="true">⌁</span><h2>Queen Lab</h2><p>Informasi pemeriksaan diagnostik, persiapan spesimen, pelaporan, dan kebutuhan fasilitas mitra.</p><a class="text-link" href="public/brand-lab.html">Kenali laboratorium →</a></article><article>${statusBadge('development','IN DEVELOPMENT')}<span class="need-icon" aria-hidden="true">◎</span><h2>Corporate Health</h2><p>Rancangan MCU, screening, layanan onsite, dan program preventive health sesuai asesmen kebutuhan organisasi.</p><a class="text-link" href="public/corporate.html">Diskusikan kebutuhan perusahaan →</a></article><article>${statusBadge('future','FUTURE DEVELOPMENT')}<span class="need-icon" aria-hidden="true">◇</span><h2>Care & Wellness</h2><p>Arah pengembangan program wellness, personal care, nutrition, dan pengalaman Queen Sanctuary.</p><a class="text-link" href="public/brand-care.html">Lihat arah pengembangan →</a></article></div></section><section class="section trust-band"><div class="wrap trust-grid"><div><p class="eyebrow">SEBELUM ANDA MEMILIH</p><h2>Informasi layanan harus dapat diverifikasi.</h2></div><div><p>Kami tidak menampilkan jadwal dokter, alamat, harga, atau izin yang belum dikonfirmasi. Hubungi tim AVA untuk memperoleh informasi sesuai fasilitas dan layanan yang sedang tersedia.</p><div class="actions">${button('public/kontak.html','Hubungi AVA')}</div></div></div></section>`);

  page('corporate.html','Corporate Health','MCU, screening, layanan onsite, preventive health dan corporate wellness berdasarkan kebutuhan perusahaan.',intro('CORPORATE HEALTH','Program kesehatan yang<br>mengikuti kebutuhan organisasi.','Untuk perusahaan, HR, HSE, komunitas, dan institusi yang membutuhkan pembahasan MCU, screening, layanan laboratorium, preventive health, atau corporate wellness.')+`<section class="section wrap"><div class="section-heading"><div><p class="eyebrow">ARSITEKTUR LAYANAN</p><h2>Mulai dari tujuan program.</h2></div><p>Lingkup akhir ditentukan setelah asesmen peserta, lokasi, jadwal, pemeriksaan, pelaporan, dan kesiapan mitra layanan.</p></div><div class="feature-grid"><article><h3>MCU & screening</h3><p>Pemetaan kebutuhan pemeriksaan dan alur peserta untuk program kesehatan perusahaan.</p></article><article><h3>Onsite coordination</h3><p>Rancangan registrasi, jadwal, alur pemeriksaan, dan koordinasi lokasi bila lingkup memungkinkan.</p></article><article><h3>Laboratory services</h3><p>Koordinasi pemeriksaan laboratorium dan hasil melalui jalur yang disepakati.</p></article><article><h3>Preventive health</h3><p>Program edukasi, pemantauan, dan tindak lanjut yang dibedakan dari diagnosis serta pengobatan.</p></article><article><h3>Corporate wellness</h3><p>Ruang pengembangan program Care & Wellness sesuai tujuan dan kesiapan organisasi.</p></article><article><h3>Digital workflow</h3><p>Portal korporat, roster peserta, dan integrasi sistem dapat dibahas bersama AVA Tech.</p></article></div></section><section class="section brand-section"><div class="wrap workflow-block"><p class="eyebrow">WORKFLOW</p><h2>Dari kebutuhan ke evaluasi.</h2><ol class="process-flow"><li>Discovery kebutuhan</li><li>Rancangan lingkup</li><li>Kesiapan peserta</li><li>Pelaksanaan</li><li>Pelaporan & evaluasi</li></ol><p class="editorial-note">Tidak ada jumlah peserta, paket, harga, atau hasil klinis yang diasumsikan pada halaman ini. Seluruhnya ditetapkan dalam proposal sesuai kebutuhan dan kemampuan layanan.</p><div class="actions"><a class="button" data-event="corporate_inquiry" href="public/kontak.html?topic=corporate">Minta Proposal Corporate Health ↗</a><a class="text-link" href="public/kemitraan.html">Lihat opsi kemitraan →</a></div></div></section>`);

  function techProduct(file,title,tag,overview,problems,features,workflow,target) {
    page(file,title,`${title} dari AVA Tech untuk alur kerja fasilitas kesehatan. Tersedia untuk demo dan pembahasan uji coba terbatas.`,intro(`AVA TECH / ${tag}`,title,overview)+`<section class="section wrap product-status-row">${statusBadge('pilot','PILOT / DEMO')}<p>Produk tersedia untuk demonstrasi. Kesiapan implementasi, integrasi, dan fitur per fasilitas ditentukan melalui asesmen serta lingkup uji coba.</p></section><section class="section wrap"><div class="product-detail-grid"><div><p class="eyebrow">PROBLEMS WE SOLVE</p><h2>Alur yang lebih mudah ditelusuri.</h2>${ul(problems)}</div><div><p class="eyebrow">KEY FEATURES</p><div class="feature-list">${features.map(([t,p])=>`<article><h3>${t}</h3><p>${p}</p></article>`).join('')}</div></div></div></section><section class="section brand-section"><div class="wrap"><p class="eyebrow">WORKFLOW</p><h2>Dari pekerjaan lapangan ke informasi yang terhubung.</h2><ol class="process-flow">${workflow.map(x=>`<li>${x}</li>`).join('')}</ol><div class="vision-grid"><div><h3>Target pengguna</h3><p>${target}</p><h3 class="spaced">Integrasi</h3><p>Kebutuhan API, perangkat, dan sistem pihak ketiga dipetakan saat discovery. Integrasi hanya dinyatakan tersedia setelah endpoint, otorisasi, dan skenario uji disepakati.</p></div><div><h3>Security & privacy</h3><p>Arsitektur aplikasi mencakup autentikasi, hak akses berbasis peran, pemisahan tenant, audit trail, dan kontrol akses data. Kesesuaian implementasi tetap perlu diverifikasi pada environment target.</p><h3 class="spaced">Implementation</h3><p>Demo → asesmen → uji coba terbatas → evaluasi → proposal implementasi. Tidak semua modul harus diaktifkan sekaligus.</p></div></div></div></section><section class="section wrap product-demo"><div><p class="eyebrow">SEE AVA TECH IN ACTION</p><h2>Gunakan skenario kerja Anda.</h2><p>Demo memakai alur dan data uji. Screenshot produk belum dipublikasikan pada website; komponen ini disiapkan untuk aset terverifikasi dari HIS, LIS, dan Apps.</p></div><div class="screenshot-placeholder" role="img" aria-label="Placeholder untuk screenshot produk ${title}"><span>PRODUCT SCREENSHOT</span><strong>TODO</strong><p>Tambahkan screenshot terverifikasi dari environment demo.</p></div></section><section class="section faq-section"><div class="wrap"><p class="eyebrow">FAQ</p><h2>Pertanyaan sebelum demo.</h2><div class="faq-list"><details><summary>Apakah seluruh fitur langsung tersedia?</summary><p>Lingkup demo mengikuti modul yang sudah tersedia. Kebutuhan tambahan dicatat sebagai konfigurasi atau pengembangan dan tidak dianggap otomatis tersedia.</p></details><details><summary>Apakah sistem dapat disesuaikan?</summary><p>Menu, alur, peran pengguna, dan integrasi dibahas melalui asesmen. Hasil asesmen menentukan kelayakan, biaya, dan jadwal.</p></details><details><summary>Bagaimana model biayanya?</summary><p>Model mencakup biaya awal untuk setup/implementasi/modul dan lisensi bulanan. Rincian diberikan setelah lingkup dipahami.</p></details></div><div class="actions"><a class="button" data-event="tech_demo_request" href="public/kontak.html?topic=demo&product=${encodeURIComponent(tag)}">Jadwalkan Demo ↗</a><a class="text-link" href="public/penawaran.html">Pelajari model penawaran →</a></div></div></section>`);
  }
  techProduct('ava-his.html','AVA HIS','HIS','Healthcare Information System untuk membantu fasilitas mengelola perjalanan pasien, dokumentasi klinis, order layanan, farmasi, billing, dan pelaporan dalam alur yang terhubung.',['Pendaftaran, antrean, dan pelayanan tersebar pada banyak pencatatan.','Order klinis, laboratorium, radiologi, dan farmasi sulit dipantau sebagai satu episode.','Billing dan status layanan membutuhkan rekonsiliasi yang jelas.'],[['Patient flow','Admisi, jadwal, antrean, EMR, rawat inap, dan tindak lanjut.'],['Integrated orders','Order laboratorium, radiologi, obat, dan tindakan dengan status terpantau.'],['Billing & reporting','Tagihan dikelola di HIS, termasuk perubahan layanan dari LIS.'],['Clinical governance','Consent, rekam medis, keselamatan pasien, audit, dan pelaporan.']],['Registrasi pasien','Pelayanan klinis','Order layanan','Pelaksanaan','Billing & laporan'],'Klinik pratama, klinik utama, dan fasilitas kesehatan yang membutuhkan alur pelayanan terintegrasi.');
  techProduct('ava-lis.html','AVA LIS','LIS','Laboratory Information System untuk mengelola order, spesimen, worklist, hasil, validasi, kendali mutu, dan hubungan hasil kembali ke HIS.',['Order dan identitas spesimen rawan terpisah.','Status pra-analitik, analitik, dan pasca-analitik sulit dipantau.','Validasi hasil, nilai kritis, QC, lot, serta jejak perubahan membutuhkan kontrol yang konsisten.'],[['Specimen workflow','Order, flebotomi, kelayakan spesimen, barcode, worklist, dan arsip.'],['Result governance','Input hasil, validasi, approval, nilai kritis, dan laporan.'],['Quality control','QC, lot verification, PME, TAT, dan audit trail.'],['Interoperability','Inbox order HIS, analyzer connector, retry, dan callback hasil.']],['Order dari HIS','Pengambilan spesimen','Pemeriksaan','Validasi','Hasil ke HIS'],'Laboratorium mandiri, laboratorium klinik, serta fasilitas yang membutuhkan pengelolaan alur diagnostik.');
  techProduct('ava-apps.html','AVA Apps','APPS','Pengalaman digital untuk pasien dan peserta program: akses layanan, booking, hasil, telehealth, serta hubungan ke program Care & Wellness sesuai fitur yang diaktifkan.',['Pengguna membutuhkan satu pintu untuk menemukan layanan dan tindak lanjut.','Booking, status, hasil, dan komunikasi sering berada pada kanal berbeda.','Program kesehatan memerlukan pengalaman digital yang tetap menjaga batas privasi.'],[['Service access','Jalur booking, status order, dan akses hasil yang dirilis.'],['Patient experience','Profil, notifikasi, riwayat, dan akses layanan melalui antarmuka publik.'],['Corporate access','Portal korporat dan roster peserta berdasarkan peran.'],['Wellness journey','Fondasi program wellness dan hubungan produk sesuai kesiapan.']],['Temukan layanan','Buat permintaan','Handoff ke HIS','Pantau status','Akses hasil'],'Pasien, peserta corporate health, keluarga, dan pengguna program yang diaktifkan oleh fasilitas.');
  const wellness=intro('QUEEN / CARE & WELLNESS','Kepedulian untuk semua.<br>Ruang untuk merawat diri.','Queen Care & Wellness menyatukan pengembangan perawatan berkelanjutan, personal care, dan pengalaman wellness untuk individu serta keluarga. Cakupannya inklusif bagi perempuan dan laki-laki.')+`<section class="section wrap vision-grid"><div><p class="eyebrow">VISI</p><h2>Menjadikan kepedulian bagian dari kehidupan sehari-hari.</h2></div><div><p class="eyebrow">MISI</p>${ul(['Memahami kebutuhan perawatan setiap individu tanpa membatasi identitas brand pada satu gender.','Menghubungkan personal care, pendampingan, dan program wellness dalam pengalaman yang jelas.','Mengembangkan program bersama mitra sesuai kebutuhan serta kemampuan layanan.','Menjaga batas antara layanan medis dan wellness agar pengguna memperoleh pendampingan yang sesuai.'])}</div></section><section class="section brand-section"><div class="wrap"><h2>Satu payung, beberapa bentuk perhatian.</h2><div class="values-grid spaced">${[['Care & kesinambungan','Koordinasi pendampingan dan kebutuhan perawatan sehari-hari, dengan keterhubungan ke layanan kesehatan bila diperlukan.'],['Personal care','Pengembangan produk perawatan diri dan kebersihan untuk kebutuhan konsumen yang beragam.'],['Wellness & kebiasaan','Program perawatan diri serta aktivitas wellness sebagai bagian dari keseharian.'],['Queen Sanctuary','Pengalaman wellness dan ruang perawatan diri dalam payung Care & Wellness.']].map(([t,p])=>`<article><h3>${t}</h3><p>${p}</p></article>`).join('')}</div></div></section><section class="section wrap"><div class="vision-grid"><div><h3>Model pengembangan bisnis</h3><p>Program bersama, pengalaman layanan, produk Queen, dan aplikasi wellness menjadi ruang pengembangan. Lingkup, kesiapan, serta bentuk kerja sama ditentukan per program.</p><h3 class="spaced">Siapa yang dituju?</h3><p>Individu, keluarga, komunitas, perusahaan, dan fasilitas mitra yang ingin mengembangkan program kepedulian serta wellness.</p></div><div><h3>Hubungan dengan unit lain</h3><p>Health menjadi jalur pelayanan klinis; Lab mendukung kebutuhan pemeriksaan; Nutrition mengembangkan portofolio produk; AVA Tech mendukung rancangan pengalaman digital.</p><h3 class="spaced">Kesiapan program</h3><p>Care & Wellness dan produk terkait merupakan bidang pengembangan. Tanyakan program serta layanan yang tersedia kepada tim AVA sebelum merencanakan kunjungan.</p></div></div><div class="actions">${button('public/kemitraan.html','Diskusikan Program Bersama')}<a class="text-link" href="public/brand-sanctuary.html">Mengenal Sanctuary →</a></div></section>`;
  page('brand-care.html','Queen Care & Wellness','Care dan wellness untuk individu serta keluarga, perempuan dan laki-laki.',wellness);
  page('brand-sanctuary.html','Queen Sanctuary','Pengalaman Sanctuary dalam payung Queen Care & Wellness.',intro('BAGIAN DARI QUEEN CARE & WELLNESS','Queen Sanctuary','Pengembangan pengalaman wellness dan ruang perawatan diri untuk semua kalangan. Sanctuary menjadi bagian dari payung Care & Wellness dalam ekosistem AVA.')+`<section class="section wrap vision-grid"><div><h2>Ruang untuk jeda.<br>Perhatian pada kenyamanan.</h2><p class="spaced">Arah pengembangan Sanctuary berfokus pada pengalaman wellness, perawatan diri, dan program bersama yang disesuaikan dengan kebutuhan peserta.</p></div><div><h3>Di dalam Care & Wellness</h3><p>Sanctuary melengkapi personal care serta pengembangan program. Layanan medis tetap memiliki jalur pelayanan klinis tersendiri.</p><h3 class="spaced">Program & kemitraan</h3><p>Ketersediaan pengalaman, jadwal, dan lingkup program dikonfirmasi dengan tim AVA. Portofolio tidak dibatasi pada layanan khusus perempuan.</p><div class="actions">${button('public/brand-care.html','Profil Care & Wellness')}</div></div></section>`);
  page('kemitraan.html','Kemitraan bisnis','Kolaborasi layanan, teknologi, corporate health, wellness dan investasi bersama AVA.',intro('GROW WITH AVA','Siapa yang dapat<br>bermitra dengan AVA?','AVA membuka percakapan dengan fasilitas kesehatan, laboratorium, perusahaan, mitra teknologi, dan mitra strategis yang memiliki kebutuhan serta kontribusi yang jelas.')+`<section class="section wrap"><div class="partnership-grid"><article><span>01</span><h2>Healthcare Provider</h2><p>Kolaborasi pelayanan, rujukan, program kesehatan, atau adopsi sistem berdasarkan lingkup dan kesiapan fasilitas.</p></article><article><span>02</span><h2>Laboratory</h2><p>Kerja sama layanan diagnostik, alur rujukan, pemetaan katalog, LIS, dan interoperabilitas sesuai kebutuhan.</p></article><article><span>03</span><h2>Clinic</h2><p>Demo HIS/Apps, integrasi layanan, pengembangan alur, dan program preventive health.</p></article><article><span>04</span><h2>Corporate</h2><p>MCU, screening, program kesehatan, layanan onsite, dan corporate wellness yang disusun melalui asesmen.</p></article><article><span>05</span><h2>Technology Partner</h2><p>API, perangkat, infrastruktur, security, dan integrasi dengan tanggung jawab teknis yang disepakati.</p></article><article><span>06</span><h2>Strategic Partner</h2><p>Kolaborasi hotel, F&amp;B, gym, olahraga, komunitas, dan bidang lain yang relevan dengan ekosistem wellness.</p></article></div><div class="partnership-principles"><div><p class="eyebrow">PRINSIP KOLABORASI</p><h2>Nilai bersama harus terlihat.</h2></div><div><p>Setiap kerja sama dimulai dari tujuan, peran, data yang dibutuhkan, batas tanggung jawab, indikator evaluasi, dan kesesuaian hukum. Nama mitra tidak akan dipublikasikan sebelum ada konfirmasi.</p><div class="actions"><a class="button" data-event="partnership_request" href="public/kontak.html?topic=partnership">Ajukan Kemitraan ↗</a><a class="text-link" href="public/investasi.html">Peluang investor →</a></div></div></div></section>`);
  const story = require('./public-company-story');
  const aboutFile=path.join(dir,'tentang.html');
  let about=fs.readFileSync(aboutFile,'utf8');
  about=about.replace(/<section class="section brand-section"><div class="wrap vision-grid"><div><p class="eyebrow">KEPEMIMPINAN[\s\S]*?<\/section>/,story.founderSummary);
  about=about.replace(section(about,'perjalanan'),`<section class="section wrap" id="perjalanan"><p class="eyebrow">CERITA & PERJALANAN</p><h2>Dari kebutuhan pelayanan menuju keterhubungan.</h2><p class="detail-lead spaced">Latar operasional laboratorium, informatika kesehatan, dan pengelolaan mutu mempertemukan pelayanan fisik dengan gagasan membangun sistem yang terhubung.</p><p>Kenali bagaimana identitas AVA dan Queen, pengembangan HIS/LIS/Apps, serta arah Care & Wellness membentuk cerita perusahaan.</p><div class="actions">${button('public/sejarah.html','Baca Cerita Lengkap')}<a class="text-link" href="public/founder.html">Mengenal Founder, Owner & CEO →</a></div></section>`);
  fs.writeFileSync(aboutFile,about);
  page('founder.html','Founder, Owner & CEO','Ace Anwar: latar dan pendekatan kepemimpinan AVA Health Solution.',story.founder);
